from lib import *
S = SS('l70')
steps = [
    step("PATH 里放一个可执行文件 git-hello(shell 脚本),git hello 甲 乙 就能运行它:参数原样传进去(参数: 甲 乙),当前目录是调用时所在的仓库目录,环境变量 GIT_EXEC_PATH 已设置。git --exec-path 给出 git 自带命令所在的目录(…/libexec/git-core,里面有 176 个文件);git help -a 的 “External commands” 一栏列出 PATH 上的 hello。git 的“子命令”机制就是找 git-<名字> 这个可执行文件,内置命令和外部命令没有本质差别。", t=tl(S(1)), mark=lidx(S(1), 'git hello 甲 乙', '我是外部子命令 git-hello', 'External commands'), done=lidx(S(1), 'GIT_EXEC_PATH 已设置', 'libexec/git-core', 'exec-path 目录里的文件数: 176'), kv=KV([['git foo', '找 git-foo 可执行文件'], ['查找位置', 'git --exec-path 和 PATH'], ['git help -a', 'External commands 列出它们']], ['git foo'])),
    step("找不到子命令时:git stauts 输出 git: 'stauts' is not a git command. See 'git --help'. 和 The most similar command is status。设 help.autocorrect=immediate 之后,git stauts 直接纠正并运行:WARNING: You called a Git command named 'stauts', which does not exist. Continuing under the assumption that you meant 'status'.,然后执行 status。", t=tl(S(2)), mark=lidx(S(2), "is not a git command", 'WARNING: You called a Git command named', 'Continuing under the assumption'), done=lidx(S(2), 'The most similar command is', 'status'), kv=KV([['默认', '给出“最相似的命令”提示'], ['help.autocorrect=immediate', '自动纠正并运行'], ['其它取值', '数字表示延迟(以 0.1 秒为单位)']], ['help.autocorrect=immediate'])),
    step("别名:alias.co = checkout,git co -b feat 输出 Switched to a new branch 'feat';alias.last = log -1 --stat --format=%s,git last 输出提交说明。以 ! 开头的别名交给 shell:alias.root = !pwd | sed … 输出仓库根目录名 l70。从子目录 sub/ 里运行 git where(!echo cwd=… GIT_PREFIX=[…]):cwd 仍是仓库根(l70),原来所在的子目录通过环境变量 GIT_PREFIX 传进来(sub/)。所以 ! 别名里要访问原来的目录得用 GIT_PREFIX。", t=tl(S(3)), mark=lidx(S(3), 'cwd=l70 GIT_PREFIX=[sub/]', "Switched to a new branch 'feat'"), done=lidx(S(3), '--- 从子目录 sub/'), kv=KV([['alias.x = 命令', '展开成 git 命令'], ['alias.x = !shell', '交给 shell,在仓库根目录运行'], ['GIT_PREFIX', '原来所在的子目录']], ['GIT_PREFIX'])),
    step("别名不能覆盖内置命令:alias.status = log --oneline 之后,git status 仍然是原来的 status(输出 On branch feat / Untracked files)。别名和外部子命令同名时,外部子命令赢:alias.hello = !echo 我是别名 hello,但 git hello 运行的仍是 PATH 上的 git-hello 脚本(输出“我是外部子命令 git-hello”),别名根本没被用到。查找顺序是 内置命令 → 外部命令 → 别名。", t=tl(S(4)), mark=lidx(S(4), 'git config alias.hello', '我是外部子命令 git-hello'), done=lidx(S(4), 'git config alias.status', 'On branch feat'), kv=KV([['内置命令', '别名不能覆盖'], ['外部命令', '同名时优先于别名'], ['顺序', '内置 → 外部 → 别名']], ['顺序'])),
    step("别名循环会被检测:alias.a = b、alias.b = a,git a 输出 fatal: alias loop detected: expansion of 'a' does not terminate: a <== b ==>。别名可以套用别名:alias.s = status,alias.ss = s -s,git ss 展开成 git s -s 再展开成 git status -s,输出 ?? sub/。", t=tl(S(5)), mark=lidx(S(5), 'alias loop detected'), done=lidx(S(5), '?? sub/', 'a <==', 'b ==>'), kv=KV([['别名套别名', '可以'], ['循环', 'fatal: alias loop detected'], ['展开', '直到不是别名为止']], ['循环'])),
    step("git co --help 输出 'co' is aliased to 'checkout',然后才是 checkout 的手册。git help -a 末尾有 “Command aliases” 一栏,列出所有别名及展开:co → checkout、hello → !echo 我是别名 hello、last、root、s、ss、where……shell 别名里可以定义函数接收参数:alias.say = !f() { echo 收到 $# 个参数: $@; }; f,git say 甲 乙 丙 输出“收到 3 个参数: 甲 乙 丙”。不带函数的 ! 别名后面的参数会被追加到命令末尾。", t=tl(S(6)), mark=lidx(S(6), "'co' is aliased to 'checkout'", 'Command aliases', '收到 3 个参数: 甲 乙 丙'), done=lidx(S(6), 'co                      checkout', 'ss                      s -s'), kv=KV([['--help', '先说明是别名'], ['git help -a', '列出所有别名'], ['函数', '! 别名里用 f() {…}; f 接收参数']], ['函数'])),
]
A = mkarti('l70', 70, 'Git,alias,外部子命令,git-foo,help.autocorrect,真实验证,动画演示',
    '实测子命令的查找:git foo 找可执行文件 git-foo(--exec-path 和 PATH);拼错命令的提示与 help.autocorrect=immediate;别名展开,! 开头的别名在仓库根目录用 shell 运行,GIT_PREFIX 保存原目录;别名不能覆盖内置命令,且与外部子命令同名时外部命令胜出(顺序:内置 → 外部 → 别名);别名循环被检测;git help -a 列出 External commands 与 Command aliases。',
    'git 的“子命令”到底是怎么找到的?为什么往 PATH 里放个 git-xxx 就多了一个 git xxx?别名能不能覆盖内置命令、和外部命令谁优先?shell 别名在哪个目录运行?这篇用几个小脚本逐个验证。',
    [('git-<名字>', '外部子命令就是 PATH(或 --exec-path)里的可执行文件,git foo 找的是 git-foo'), ('内置 → 外部 → 别名', '同名时的优先顺序,别名既不能覆盖内置命令,也盖不过 PATH 上的外部命令'), ('GIT_PREFIX', '! 别名总是在仓库根目录运行,原来所在的子目录通过这个环境变量传入')],
    [('外部子命令', '<p>git 找不到内置的 <code>foo</code> 时去找可执行文件 <code>git-foo</code>:先在 <code>git --exec-path</code>,再在 <code>PATH</code> 里。运行时参数原样传入、当前目录是调用时的目录。<code>git help -a</code> 的 “External commands” 列出它们。</p>'),
     ('输错了', '<p>默认只提示最相似的命令;<code>help.autocorrect=immediate</code> 会直接纠正并运行(数字则表示延迟,单位 0.1 秒)。</p>'),
     ('别名', '<p><code>alias.co = checkout</code> 展开成 git 命令;以 <code>!</code> 开头的别名交给 shell,在仓库根目录运行,原来的子目录在环境变量 <code>GIT_PREFIX</code> 里。</p>'),
     ('优先级', '<p>别名不能覆盖内置命令(<code>alias.status</code> 被忽略);与 PATH 上的外部命令同名时外部命令赢。顺序:内置 → 外部 → 别名。</p>'),
     ('套用与循环', '<p>别名可以套用别名(<code>ss = s -s</code>,<code>s = status</code>),循环会被检测并报 <code>alias loop detected</code>。</p>'),
     ('查看与传参', '<p><code>git x --help</code> 先说明它是别名;<code>git help -a</code> 的 “Command aliases” 列出全部;shell 别名用函数 <code>f() { … }; f</code> 接收参数。</p>')],
    steps,
    [ENV_I_GIT + '。外部子命令是实验目录里的 shell 脚本(PATH 前面加了实验目录);alias 的优先级结果是在这台机器的 git 2.54.0 上观察到的(别名与外部命令同名时外部命令胜出),没有读源码也没有查其它版本',
     '没有验证:别名里使用 git 命令选项的 alias.* 命令行解析细节;core.pager 对别名的影响;git-lfs 等真实外部命令的安装方式;Windows 上可执行文件的查找(.exe);GIT_EXEC_PATH 环境变量覆盖;completion 对别名的支持'],
    '别名与外部子命令')
